package dev.workshopvideo;
import android.graphics.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.nio.file.*;import dev.workshopvideo.core.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE,application=android.app.Application.class) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SceneGraphicsChecks {
 private File workshop(String id){String directory=System.getenv("WVB_WORKSHOP_DIR");org.junit.Assume.assumeTrue("Set WVB_WORKSHOP_DIR to run optional workshop samples",directory!=null&&!directory.isBlank());File source=new File(directory,id+"/scene.pkg");org.junit.Assume.assumeTrue("Optional workshop sample is missing: "+id,source.isFile());return source;}
 private WallpaperContent.Scene scene(int color){WallpaperContent.Scene s=new WallpaperContent.Scene();s.width=64;s.height=64;WallpaperContent.Layer l=new WallpaperContent.Layer();l.w=64;l.h=64;l.bitmap=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);l.bitmap.eraseColor(color);s.layers.add(l);return s;}
 private Bitmap draw(WallpaperContent.Scene s,JSONObject options,boolean touch){Bitmap out=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(out);c.drawColor(Color.BLACK);ScenePainter.layers(c,s,new Paint(3),options,new EffectMotion.Frame(0,0,1,0),32,32,touch);return out;}
 @Test public void missingLayerOffsetsRenderActualPixels()throws Exception{try(WallpaperContent.Scene s=scene(Color.RED)){Bitmap live=draw(s,EffectOptions.normalize(null),false);assertEquals(Color.RED,live.getPixel(32,32));ScenePainter.verify(live);Bitmap poster=ScenePainter.poster(s,64);assertTrue(live.sameAs(poster));JSONObject explicit=EffectOptions.normalize(null);explicit.put("layerX0",0).put("layerY0",0);assertTrue(live.sameAs(draw(s,explicit,false)));}}
 @Test public void nonFiniteLayerTransformShowsWhyOldCodeWentBlack()throws Exception{try(WallpaperContent.Scene s=scene(Color.RED)){Bitmap old=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(old);c.drawColor(Color.BLACK);c.translate((float)new JSONObject().optDouble("missingX"),(float)new JSONObject().optDouble("missingY"));c.drawBitmap(s.layers.get(0).bitmap,0,0,null);assertEquals(Color.BLACK,old.getPixel(32,32));}}
 @Test public void xrayTouchRevealsOnlyItsImageRegion()throws Exception{try(WallpaperContent.Scene s=scene(Color.RED)){WallpaperContent.Layer l=s.layers.get(0);l.reveal=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);l.reveal.eraseColor(Color.BLUE);l.revealSize=.4f;Bitmap off=draw(s,new JSONObject(),false),on=draw(s,new JSONObject(),true);assertEquals(Color.RED,off.getPixel(32,32));assertEquals(Color.BLUE,on.getPixel(32,32));assertEquals(Color.RED,on.getPixel(0,0));assertEquals(Color.RED,draw(s,new JSONObject().put("xray",false),true).getPixel(32,32));}}
 @Test public void blankSceneIsRejectedByActualPixelGate()throws Exception{for(int color:new int[]{Color.BLACK,Color.TRANSPARENT})try(WallpaperContent.Scene s=scene(color)){Bitmap output=ScenePainter.poster(s,64);boolean rejected=false;try{ScenePainter.verify(output);}catch(IOException expected){rejected=true;}assertTrue(rejected);}}
 @Test public void layerOpacityAndMovementAreAppliedInLivePath()throws Exception{try(WallpaperContent.Scene s=scene(Color.GREEN)){JSONObject moved=new JSONObject().put("layerX0",.5);Bitmap output=draw(s,moved,false);assertEquals(Color.BLACK,output.getPixel(4,32));assertEquals(Color.GREEN,output.getPixel(60,32));JSONObject hidden=new JSONObject().put("opacity0",0);assertEquals(Color.BLACK,draw(s,hidden,false).getPixel(32,32));}}
 @Test public void realXrayAdmissionAndSerializedReveal()throws Exception{
  File workspace=new File(System.getProperty("graphics.work"));workspace.mkdirs();JSONObject results=new JSONObject();
  for(String id:new String[]{"2297826176","2262867800","3213046325"}){
   File source=workshop(id);SceneAdapter.Report report=SceneAdapter.inspect(source,workspace);
   try{results.put(id,new JSONObject().put("usable",report.usable()).put("reason",report.error).put("xrays",report.xrays).put("layers",report.scene.layers.size()));
    if(id.equals("2297826176")){assertTrue(report.describe(),report.usable());assertEquals(1,report.xrays);File adapted=new File(workspace,id+".zip");SceneAdapter.write(report,adapted);try(WallpaperContent.Scene s=WallpaperContent.scene(adapted)){Bitmap poster=ScenePainter.poster(s,512);ScenePainter.verify(poster);try(FileOutputStream out=new FileOutputStream(new File(workspace,id+".png"))){poster.compress(Bitmap.CompressFormat.PNG,100,out);}assertNotNull(s.layers.get(1).reveal);JSONObject off=EffectOptions.normalize(null);Bitmap screen=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);Canvas surface=new Canvas(screen);surface.drawColor(Color.BLACK);surface.scale(512f/s.width,512f/s.height);ScenePainter.layers(surface,s,new Paint(3),off,new EffectMotion.Frame(0,0,1,0),256,256,false);ScenePainter.verify(screen);}}
    // Unsupported X-ray variants drop only the reveal; the layer and its other effects stay.
    else {assertTrue(report.describe(),report.usable());assertEquals(0,report.xrays);assertTrue(report.describe(),report.droppedEffects.containsKey("xray"));assertTrue(report.describe(),report.describe().contains("xray（X-ray"));}
   }finally{report.scene.close();}
  }
  Files.writeString(new File(workspace,"xray-results.json").toPath(),results.toString(2));
 }
 @Test public void realLandscapePackagesProduceVisibleAndroidPixels()throws Exception{
  File workspace=new File(System.getProperty("graphics.work"));workspace.mkdirs();
  for(String id:new String[]{"1962375063","1888636115","1132505365","3483582101","3713073223","3601075812"}){
   SceneAdapter.Report report=SceneAdapter.inspect(workshop(id),workspace);
   try{assertTrue(report.describe(),report.usable());Bitmap poster=ScenePainter.poster(report.scene,512);ScenePainter.verify(poster);try(FileOutputStream out=new FileOutputStream(new File(workspace,id+".png"))){poster.compress(Bitmap.CompressFormat.PNG,100,out);}}finally{report.scene.close();}
  }
 }

 @Test public void relativeDragKeepsXrayUnderFinger()throws Exception{
  WallpaperEffects a=new WallpaperEffects(),b=new WallpaperEffects();JSONObject o=new JSONObject().put("touch",true);a.options(o);b.options(o);a.touch(.1f,.2f,0);b.touch(.7f,.7f,0);idle();assertEquals(0,a.frame(false).x(),.00001);assertEquals(0,b.frame(false).x(),.00001);
  a.touch(.3f,.3f,2);b.touch(.9f,.8f,2);for(int i=0;i<25;i++){idle();a.frame(false);b.frame(false);}assertTrue(a.frame(false).x()>0);assertEquals(a.tx,b.tx,.0001);assertEquals(.3f,a.pointerX(),.00001);assertEquals(.9f,b.pointerX(),.00001);assertTrue(a.pointerDown());a.touch(.3f,.3f,1);for(int i=0;i<100;i++){idle();a.frame(false);}assertEquals(0,a.tx,.0002);assertFalse(a.pointerDown());
 }
 private void idle(){org.robolectric.shadows.ShadowSystemClock.advanceBy(java.time.Duration.ofMillis(16));}
 @Test public void gyroReversalsAndFitAreApplied()throws Exception{
  WallpaperEffects e=new WallpaperEffects();JSONObject o=new JSONObject().put("gyro",true).put("strength",1);e.options(o);e.tilt(.8f,-.4f);for(int i=0;i<100;i++){idle();e.frame(false);}assertTrue(e.frame(false).x()>0);assertTrue(e.frame(false).y()<0);o.put("reverseX",true).put("reverseY",true);e.options(o);for(int i=0;i<100;i++){idle();e.frame(false);}assertTrue(e.frame(false).x()<0);assertTrue(e.frame(false).y()>0);assertEquals(0,e.frame(true).x(),0);assertEquals(0,e.frame(true).y(),0);
 }
 @Test public void layerDepthRotationAndColorControlsChangeActualPixels()throws Exception{
  try(WallpaperContent.Scene s=scene(Color.RED)){WallpaperContent.Layer l=s.layers.get(0);l.w=16;l.h=16;l.x=8;l.y=8;l.depth=1;Bitmap out=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(out);c.drawColor(Color.BLACK);ScenePainter.layers(c,s,new Paint(3),new JSONObject(),new EffectMotion.Frame(.5f,0,1,0),0,0,false);assertEquals(Color.BLACK,out.getPixel(10,10));assertEquals(Color.RED,out.getPixel(26,10));
   out.eraseColor(Color.BLACK);ScenePainter.layers(c,s,new Paint(3),new JSONObject().put("depth0",0),new EffectMotion.Frame(.5f,0,1,0),0,0,false);assertEquals(Color.RED,out.getPixel(10,10));
   l.w=32;l.h=8;l.x=16;l.y=28;l.rotation=90;out.eraseColor(Color.BLACK);ScenePainter.layers(c,s,new Paint(3),new JSONObject(),null,0,0,false);assertEquals(Color.RED,out.getPixel(32,20));assertEquals(Color.BLACK,out.getPixel(20,32));
  }
  WallpaperEffects e=new WallpaperEffects();e.options(new JSONObject().put("saturation",0).put("brightness",.5));Bitmap src=Bitmap.createBitmap(8,8,Bitmap.Config.ARGB_8888);src.eraseColor(Color.RED);Bitmap out=Bitmap.createBitmap(8,8,Bitmap.Config.ARGB_8888);Paint p=new Paint();p.setColorFilter(e.colorFilter());new Canvas(out).drawBitmap(src,0,0,p);int pixel=out.getPixel(4,4);assertEquals(Color.red(pixel),Color.green(pixel));assertEquals(Color.green(pixel),Color.blue(pixel));assertTrue(Color.red(pixel)>0&&Color.red(pixel)<128);
 }
 @Test public void overlayColorsAffectParticlesAndRippleWhileLegacyClockIsIgnored()throws Exception{
  WallpaperEffects e=new WallpaperEffects();JSONObject settings=new JSONObject().put("clock",true).put("clockSize",64);e.options(settings);assertFalse(e.options.has("clock"));assertFalse(e.options.has("clockSize"));Bitmap out=Bitmap.createBitmap(360,640,Bitmap.Config.ARGB_8888);e.overlay(new Canvas(out),360,640);int[] pixels=new int[360*640];out.getPixels(pixels,0,360,0,0,360,640);for(int pixel:pixels)assertEquals(0,pixel);
  for(String mode:new String[]{"particles","ripple"}){settings=new JSONObject().put(mode,true).put("color","#ffadc4");e.options(settings);e.touch(.5f,.5f,0);org.robolectric.shadows.ShadowSystemClock.advanceBy(java.time.Duration.ofMillis(250));out.eraseColor(0);e.overlay(new Canvas(out),360,640);out.getPixels(pixels,0,360,0,0,360,640);int lit=0;for(int pixel:pixels)if(Color.alpha(pixel)>32){lit++;assertTrue(Color.red(pixel)>Color.green(pixel));}assertTrue(mode+" visible colored pixels",lit>0);}
 }
 private android.view.View find(android.view.View view,String text){if(view instanceof android.widget.TextView&&((android.widget.TextView)view).getText().toString().equals(text))return view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)view;for(int i=0;i<g.getChildCount();i++){android.view.View found=find(g.getChildAt(i),text);if(found!=null)return found;}}return null;}
 private android.view.View tag(android.view.View view,String value){if(value.equals(view.getTag()))return view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)view;for(int i=0;i<g.getChildCount();i++){android.view.View found=tag(g.getChildAt(i),value);if(found!=null)return found;}}return null;}
 @Test public void paletteSelectionToggleAndResetWorkInActualAndroidWidgets()throws Exception{
  try(var controller=Robolectric.buildActivity(android.app.Activity.class).setup()){
   var changed=new java.util.concurrent.atomic.AtomicReference<JSONObject>();EffectPanel panel=new EffectPanel(controller.get(),new JSONObject().put("clock",true),true,"image",changed::set);controller.get().setContentView(panel);
   assertNull(find(panel,"实时时钟"));assertNull(tag(panel,"effect-color"));((android.widget.Switch)find(panel,"触摸波纹")).setChecked(true);assertNotNull(tag(panel,"effect-color"));tag(panel,"effect-color").performClick();android.app.Dialog dialog=org.robolectric.shadows.ShadowDialog.getLatestDialog();android.view.View decor=dialog.getWindow().getDecorView();tag(decor,"preset-8").performClick();find(decor,"使用此颜色").performClick();assertEquals("#FFADC4",changed.get().optString("color"));org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();((android.widget.Switch)find(panel,"触摸波纹")).setChecked(false);assertNull(tag(panel,"effect-color"));((android.widget.Switch)find(panel,"漂浮粒子")).setChecked(true);assertNotNull(tag(panel,"effect-color"));find(panel,"恢复默认效果").performClick();assertNull(tag(panel,"effect-color"));assertFalse(changed.get().has("clock"));
  }
 }
 @Test public void resettingSceneControlsRetainsRealLayerAndXrayCapabilities()throws Exception{
  try(org.robolectric.android.controller.ActivityController<android.app.Activity> controller=Robolectric.buildActivity(android.app.Activity.class).setup()){
   EffectPanel panel=new EffectPanel(controller.get(),new JSONObject(),false,"scene",ignored->{});panel.sceneLayers(new float[]{.2f,.8f},new String[]{"背景图层","前景图层"},true);assertNotNull(find(panel,"背景图层"));assertNotNull(find(panel,"按住并拖动查看另一层图片"));find(panel,"恢复默认效果").performClick();assertNotNull(find(panel,"背景图层"));assertNotNull(find(panel,"前景图层"));assertNotNull(find(panel,"按住并拖动查看另一层图片"));
  }
 }
 @Test public void actualCanvasPagingCoversEntireImageForChangingLauncherPageCounts()throws Exception{
  File file=new File(System.getProperty("graphics.work"),"paging-gradient.png");Bitmap source=Bitmap.createBitmap(192,64,Bitmap.Config.ARGB_8888);for(int x=0;x<192;x++)for(int y=0;y<64;y++)source.setPixel(x,y,Color.rgb(x,255-x,x/2));try(FileOutputStream out=new FileOutputStream(file)){source.compress(Bitmap.CompressFormat.PNG,100,out);}
  File sceneFile=new File(System.getProperty("graphics.work"),"paging-gradient.zip");try(java.util.zip.ZipOutputStream zip=new java.util.zip.ZipOutputStream(new FileOutputStream(sceneFile))){zip.putNextEntry(new java.util.zip.ZipEntry("wallpaper-mobile.json"));zip.write(new JSONObject().put("format","WallpaperMobileScene/1").put("width",192).put("height",64).put("layers",new JSONArray().put(new JSONObject().put("file","gradient.png"))).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));zip.closeEntry();zip.putNextEntry(new java.util.zip.ZipEntry("gradient.png"));zip.write(Files.readAllBytes(file.toPath()));zip.closeEntry();}
  WallpaperEffects e=new WallpaperEffects();e.options(new JSONObject().put("zoom",1).put("pan",true).put("scrollStrength",.5));assertFalse(e.options.has("scrollStrength"));JSONObject config=new JSONObject().put("pan",true).put("effects",e.options);CanvasWallpaper renderer=new CanvasWallpaper(null,64,64,sceneFile,config,new android.os.Handler(android.os.Looper.getMainLooper()),e,null);java.lang.reflect.Method paint=CanvasWallpaper.class.getDeclaredMethod("paint",Canvas.class,int.class,int.class);paint.setAccessible(true);
  try{for(int count:new int[]{2,3,5,8}){for(int page=0;page<count;page++){e.offset=WallpaperPaging.atPage(page,count);Bitmap frame=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);paint.invoke(renderer,new Canvas(frame),64,64);float expected=32+128*page/(float)(count-1);assertEquals("page "+page+"/"+count,expected,Color.red(frame.getPixel(32,32)),1.5);if(page==0)assertEquals(0,Color.red(frame.getPixel(0,32)),1);if(page==count-1)assertEquals(191,Color.red(frame.getPixel(63,32)),1);try(FileOutputStream out=new FileOutputStream(new File(System.getProperty("graphics.work"),"paging-"+count+"-"+page+".png"))){frame.compress(Bitmap.CompressFormat.PNG,100,out);}frame.recycle();}}}
  finally{renderer.close();source.recycle();}
 }
}
